import {
    Table,
    StringColumn,
    GenericColumn,
    ReferenceColumn,
    DateColumn,
    IntegerColumn,
    GuidColumn,
} from '@servicenow/sdk/core'

export const sc_request = Table({
    actions: ['read', 'update', 'create'],
    allowClientScripts: true,
    allowNewFields: true,
    allowUiActions: true,
    allowWebServiceAccess: true,
    attributes: {
        hasWorkflow: true,
    },
    audit: true,
    autoNumber: {
        number: 10000,
        prefix: 'REQ',
    },
    extends: 'task',
    extensible: true,
    label: 'Request',
    licensingConfig: {
        licenseCondition: 'sys_updated_byNSAMEASrequested_for.user_name^request_state!=requested^EQ',
    },
    name: 'sc_request',
    schema: {
        special_instructions: StringColumn({
            label: 'Special instructions',
            maxLength: 4000,
        }),
        price: GenericColumn({
            columnType: 'currency',
            label: 'Price',
            maxLength: 20,
            readOnly: true,
        }),
        parent_interaction: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Parent interaction',
            referenceTable: 'interaction',
        }),
        requested_date: DateColumn({
            label: [
                {
                    hint: 'Desired delivery date',
                    label: 'Requested for date',
                    plural: 'Requested for dates',
                    language: 'en',
                },
            ],
        }),
        requested_for: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            default: 'javascript:gs.getUserID()',
            label: [
                {
                    hint: 'On behalf of another individual',
                    label: 'Requested for',
                    plural: 'Requested for',
                    language: 'en',
                },
            ],
            referenceTable: 'sys_user',
        }),
        delivery_address: StringColumn({
            label: 'Delivery address',
            maxLength: 4000,
        }),
        stage: GenericColumn({
            columnType: 'workflow',
            default: 'requested',
            dropdown: 'dropdown_with_none',
            label: 'Stage',
            maxLength: 80,
        }),
        calendar_stc: IntegerColumn({
            label: 'Resolve Time',
        }),
        request_state: StringColumn({
            default: 'requested',
            dropdown: 'dropdown_with_none',
            label: 'Request state',
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
    },
    textIndex: true,
})
